import * as fs from 'node:fs';
import * as path from 'node:path';
import type { ProcDef } from '../defineProc.js';
import { procSignature } from './ddl.js';

export interface BuildGrantsOpts {
  /**
   * Procs to emit grants for. Each proc's `roles` field decides which logical
   * roles get `GRANT USAGE ON PROCEDURE`. Procs with no `roles` are skipped.
   */
  procs: Array<ProcDef<string, unknown, unknown>>;
  /** Output file path. Parent dirs are created if missing. */
  out: string;
  /** How to render a logical role as a target. Default: `ROLE IDENTIFIER($<role>_role)`. */
  roleTarget?: (logicalRole: string) => string;
  /**
   * SQL block to prepend (e.g. `SET admin_role = 'PARAM_ROLLOUT_ADMIN';`).
   * Lets the build-script wire in default mappings without forcing operators
   * to set them by hand.
   */
  preamble?: string;
  /**
   * If set, emit `GRANT USAGE ON MCP SERVER <name>` for every role that has
   * at least one proc grant. Required so non-admin roles can connect to the
   * Snowflake-managed MCP server registered alongside the procs in sproc
   * mode. Per-tool RBAC is still enforced by the proc-level GRANTs above.
   */
  mcpServerName?: string;
  /**
   * Fully-qualified audit table name (e.g. `SYNAPSE.MTG_INTELLIGENCE.VERB_ATTEMPT`).
   * Emitted as `GRANT INSERT, SELECT ON TABLE <auditTable>` for every role that
   * has USAGE on at least one CALLER-mode proc — those procs' bodies write to
   * the audit table under the caller's role, so the caller must have DML on it.
   * OWNER-mode procs don't need this (their bodies run as the schema owner).
   */
  auditTable?: string;
}

function defaultRoleTarget(logicalRole: string): string {
  return `ROLE IDENTIFIER($${logicalRole}_role)`;
}

/**
 * Generate per-role `GRANT USAGE ON PROCEDURE` blocks from a registry. Output
 * is grouped by logical role for legibility; each block lists procs sorted by
 * name. Roles map to actual Snowflake roles via `IDENTIFIER($<role>_role)` —
 * operators set those vars before running install.sql.
 */
interface RollupResult {
  /** logical role -> procs it can invoke */
  byRole: Map<string, Array<ProcDef<string, unknown, unknown>>>;
  /** roles that have at least one CALLER-mode proc (need audit-table DML) */
  callerRoles: Set<string>;
}

function rollupProcRoles(procs: ReadonlyArray<ProcDef<string, unknown, unknown>>): RollupResult {
  const byRole = new Map<string, Array<ProcDef<string, unknown, unknown>>>();
  const callerRoles = new Set<string>();
  for (const proc of procs) {
    const isCaller = proc.executeAs === 'CALLER';
    for (const r of proc.roles ?? []) {
      let list = byRole.get(r);
      if (!list) { list = []; byRole.set(r, list); }
      list.push(proc);
      if (isCaller) callerRoles.add(r);
    }
  }
  return { byRole, callerRoles };
}

export async function buildGrants(opts: BuildGrantsOpts): Promise<void> {
  const target = opts.roleTarget ?? defaultRoleTarget;
  const { byRole, callerRoles } = rollupProcRoles(opts.procs);

  const parts: string[] = [
    '-- Generated by @snowflake/synapse/build. Do not edit.',
    '-- Per-role GRANT USAGE blocks. Roles bound through IDENTIFIER($..._role)',
    '-- so operators can remap logical -> actual roles via SET at install time.',
    '',
  ];
  if (opts.preamble) {
    parts.push(opts.preamble.trimEnd(), '');
  }

  const sortedRoles = [...byRole.keys()].sort();
  for (const role of sortedRoles) {
    parts.push(`-- role: ${role}`);
    const procs = byRole.get(role)!;
    procs.sort((a, b) => a.name.localeCompare(b.name));
    for (const p of procs) {
      parts.push(`GRANT USAGE ON PROCEDURE ${p.name}${procSignature(p)} TO ${target(role)};`);
    }
    if (opts.mcpServerName) {
      parts.push(`GRANT USAGE ON MCP SERVER ${opts.mcpServerName} TO ${target(role)};`);
    }
    if (opts.auditTable && callerRoles.has(role)) {
      parts.push(`GRANT INSERT, SELECT ON TABLE ${opts.auditTable} TO ${target(role)};`);
    }
    parts.push('');
  }

  await fs.promises.mkdir(path.dirname(opts.out), { recursive: true });
  await fs.promises.writeFile(opts.out, parts.join('\n'), 'utf8');
}
